package com.vault.controller;import com.vault.dto.*;import com.vault.service.AccountService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/users/me")public class UserController{private final AccountService service;public UserController(AccountService s){service=s;}@GetMapping public Views.UserView me(Authentication a){return Views.UserView.from(service.current(a.getName()));}@PutMapping public Views.UserView update(Authentication a,@Valid @RequestBody Requests.Profile x){return service.update(a.getName(),x);}@PutMapping("/password")public void password(Authentication a,@Valid @RequestBody Requests.ChangePassword x){service.password(a.getName(),x);}}
